-- Swim Records CSV Import — SQL Edition
-- Generated from: swimRecords_rows.csv (100 rows → 92 with duration > 0)
-- Run in Supabase SQL Editor or via: psql $DATABASE_URL -f import_swim_records.sql
--
-- 5 malformed CSV row IDs replaced with generated UUIDs (non-standard format):
--   6eOuAvQovgXBDKXVHizD, AeCoVHfy5YbdD7HxptEK, B7qIOw2fduDPshcmLr7D,
--   ctBzb8m9iPzNBRrEurvl, EpYYMoYKlIVMMisSX6Fx
--
-- Intensity derived from heart_rate: null/0/1-139= easy, 140-159= moderate, 160-174= hard, 175+= race
-- Stroke normalized: FR/FR /'' → Freestyle
-- 37 sessions, 37 workouts, 92 recorded_time rows

BEGIN;

ON CONFLICT (auth_id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET stroke = EXCLUDED.stroke, pace_distance = EXCLUDED.pace_distance, time_ms = EXCLUDED.time_ms, intensity = EXCLUDED.intensity;
COMMIT;

